# Perform BFS from start node to find nodes at exactly depth 5
from collections import deque

def bfs_at_depth(graph, start, target_depth):
    """Find all nodes at exactly target_depth from start node using BFS"""
    if target_depth == 0:
        return set()

    visited = set([start])
    queue = deque([(start, 0)])  # (node, depth)
    depth_nodes = {i: set() for i in range(target_depth + 1)}

    while queue:
        node, depth = queue.popleft()

        if depth >= target_depth:
            continue

        for neighbor in graph.get(node, []):
            if neighbor not in visited:
                visited.add(neighbor)
                new_depth = depth + 1
                depth_nodes[new_depth].add(neighbor)
                queue.append((neighbor, new_depth))

    return depth_nodes[target_depth]

